#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'

class ConfError extends Error {}
const fail = (m) => { throw new ConfError(m) }

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const newTable = () => ({ type: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'

function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  for (let n = 0; n < lines.length; n++) {
    try {
      current = parseLine(lines[n], root, current)
    } catch (e) {
      if (e instanceof ConfError) {
        process.stderr.write(`error: line ${n + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }
  return root
}

function parseLine(line, root, current) {
  let i = 0
  const skipWs = () => { while (i < line.length && isWs(line[i])) i++ }
  const atEnd = () => { skipWs(); return i >= line.length || line[i] === '#' || line[i] === ';' }
  skipWs()
  if (i >= line.length || line[i] === '#' || line[i] === ';') return current

  function parseString(q) {
    i++
    let s = ''
    for (;;) {
      if (i >= line.length) fail('unterminated string')
      const c = line[i]
      if (c === q) { i++; return s }
      if (q === '"' && c === '\\') {
        i++
        if (i >= line.length) fail('unterminated string')
        const e = line[i]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { s += map[e]; i++ } else if (e === 'u') {
          const h = line.slice(i + 1, i + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          s += String.fromCharCode(parseInt(h, 16)); i += 5
        } else fail(`invalid escape \\${String.fromCodePoint(line.codePointAt(i))}`)
        continue
      }
      s += c; i++
    }
  }

  function parseName() {
    skipWs()
    const c = line[i]
    if (c === '"' || c === "'") return parseString(c)
    const st = i
    while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) i++
    if (i === st) fail('expected a name')
    return line.slice(st, i)
  }

  function parseDotted() {
    const names = [parseName()]
    for (;;) {
      skipWs()
      if (line[i] === '.') { i++; names.push(parseName()) } else return names
    }
  }

  // Walk the key path (all but the last name), creating tables on the way.
  function walk(base, names, prefix) {
    let t = base
    const path = [...prefix]
    for (const name of names) {
      path.push(name)
      let child = t.map.get(name)
      if (!child) { child = newTable(); t.map.set(name, child) }
      if (child.type === 'array' && child.aot) child = child.items[child.items.length - 1]
      if (child.type !== 'table') fail(`${path.join('.')} is not a table`)
      t = child
    }
    return t
  }

  function parseValue(inContainer) {
    skipWs()
    const c = line[i]
    if (i >= line.length || c === '#' && false) fail('expected a value')
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { type: 'string', value: parseString(c) }
    if (c === '[') {
      i++
      const items = []
      for (;;) {
        if (atEnd()) fail('unterminated array')
        if (line[i] === ']') { i++; return { type: 'array', items, aot: false } }
        items.push(parseValue(true))
        if (atEnd()) fail('unterminated array')
        if (line[i] === ',') { i++; continue }
        if (line[i] === ']') continue
        fail('unterminated array')
      }
    }
    if (c === '{') {
      i++
      const t = newTable()
      let first = true
      for (;;) {
        if (atEnd()) fail('unterminated inline table')
        if (line[i] === '}' && first) { i++; return t }
        first = false
        const names = parseDotted()
        skipWs()
        if (line[i] !== '=') fail('expected = in an inline table')
        i++
        assign(t, names, parseValue(true), [])
        if (atEnd()) fail('unterminated inline table')
        if (line[i] === ',') { i++; continue }
        if (line[i] === '}') { i++; return t }
        fail('unterminated inline table')
      }
